extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var west := main.get_node_or_null("BlockWest") as Node3D
	if not check("west", west != null, "Nella scena serve un Node3D chiamato BlockWest figlio di Island"):
		return
	var bridge := main.get_node_or_null("BlockWest/BlockWestBridge") as Node3D
	if not check("bridge", bridge != null, "BlockWest deve avere un figlio Node3D chiamato BlockWestBridge"):
		return
	check("west_pos", west.position.is_equal_approx(Vector3(-5.0, 0.0, 2.0)), "BlockWest deve avere posizione locale (-5, 0, 2) (trovata: %s)" % str(west.position))
	check("west_rot", absf(west.rotation_degrees.y - 45.0) < 0.1, "BlockWest deve avere rotazione Y di 45 gradi (trovata: %.1f)" % west.rotation_degrees.y)
	check("west_scale", west.scale.is_equal_approx(Vector3(2.0, 1.0, 2.0)), "BlockWest deve avere scala (2, 1, 2) (trovata: %s)" % str(west.scale))
	check("bridge_pos", bridge.position.is_equal_approx(Vector3(0.0, 2.0, -3.0)), "BlockWestBridge deve avere posizione locale (0, 2, -3) (trovata: %s)" % str(bridge.position))
